target=os.environ['STAMPED_JUDGE_TARGET']
errors=[]
for e in m['entries']:
 p=os.path.join(root,e['path'])
 if not os.path.lexists(p): errors.append((e['path'],'missing')); continue
 if e['kind']=='file':
  h=hashlib.sha256(open(p,'rb').read()).hexdigest()
  if h!=e['sha256']: errors.append((e['path'],'sha256 mismatch'))
 elif e['kind']=='symlink' and os.readlink(p)!=e.get('target'): errors.append((e['path'],'link mismatch'))
print('manifest entries',len(m['entries']),'errors/omissions',len(m.get('errors',[])),len(m.get('omissions',[])),'entry mismatches',len(errors))
